extract() {
  case "$1" in
    *.md) grep -oE 'retry-s01-t02-[0-9]{6}\*\* \| System: [a-z0-9_-]+ \| Status: [a-z-]+' "$1" | sed -E 's/\*\* \| System: /,/; s/ \| Status: /,/' ;;
    *.jsonl) python3 -c "
import json,sys
for line in open('$1'):
    r=json.loads(line)
    print(f\"{r['case']},{r['system']},{r['status']}\")
" ;;
    *.csv) python3 -c "
import csv,sys
with open('$1') as f:
    r=csv.DictReader(f)
    for row in r:
        print(f\"{row['case']},{row['system']},{row['status']}\")
" ;;
    *.yaml) python3 -c "
import re
text=open('$1').read()
entries=re.findall(r'case: (\S+)\s+system: (\S+)\s+status: (\S+)', text)
for e in entries:
    print(','.join(e))
" ;;
    *.log) grep -oE 'case=\S+ system=\S+ status=\S+' "$1" | sed -E 's/case=//; s/ system=/,/; s/ status=/,/' ;;
  esac
}
for f in retry-s01-t02-evidence-01.md retry-s01-t02-evidence-02.jsonl retry-s01-t02-evidence-03.csv retry-s01-t02-evidence-04.yaml retry-s01-t02-evidence-05.log; do
  extract "$f" > "/tmp/norm_$f.csv"
  echo "$f -> $(wc -l < /tmp/norm_$f.csv) normalized rows"
done

