cd /private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-xa2ygylo/retry-s01-worker-crash && python3 - <<'PY'
import re, json, csv, hashlib

base = "maintenance/inputs/retry-s01/journal-schema-notes"

def parse_md(path):
    records = {}
    with open(path) as f:
        for line in f:
            m = re.match(r"- \*\*(retry-s01-t04-\d{6})\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.+)$", line.strip())
            if m:
                case, system, status, note = m.groups()
                records[case] = (system, status, note)
    return records

def parse_jsonl(path):
    records = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            records[obj["case"]] = (obj["system"], obj["status"], obj["note"])
    return records

def parse_csv(path):
    records = {}
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            records[row["case"]] = (row["system"], row["status"], row["note"])
    return records

def parse_yaml(path):
    # Simple hand-rolled parser matching the fixed structure of this file.
    records = {}
    with open(path) as f:
        lines = [l.rstrip("\n") for l in f]
    i = 0
    cur = {}
    case = None
    for line in lines:
        if line.startswith("- case:"):
            if case is not None:
                records[case] = (cur["system"], cur["status"], cur["note"])
            case = line.split(":", 1)[1].strip()
            cur = {}
        elif line.strip().startswith("system:"):
            cur["system"] = line.split(":", 1)[1].strip()
        elif line.strip().startswith("status:"):
            cur["status"] = line.split(":", 1)[1].strip()
        elif line.strip().startswith("note:"):
            note = line.split(":", 1)[1].strip()
            if note.startswith('"') and note.endswith('"'):
                note = note[1:-1]
            cur["note"] = note
    if case is not None:
        records[case] = (cur["system"], cur["status"], cur["note"])
    return records

def parse_log(path):
    records = {}
    pat = re.compile(r'case=(retry-s01-t04-\d{6}) system=(\S+) status=(\S+) note="(.+)"$')
    with open(path) as f:
        for line in f:
            m = pat.match(line.strip())
            if m:
                case, system, status, note = m.groups()
                records[case] = (system, status, note)
    return records

files = {
    "retry-s01-t04-evidence-01.md": parse_md(f"{base}/retry-s01-t04-evidence-01.md"),
    "retry-s01-t04-evidence-02.jsonl": parse_jsonl(f"{base}/retry-s01-t04-evidence-02.jsonl"),
    "retry-s01-t04-evidence-03.csv": parse_csv(f"{base}/retry-s01-t04-evidence-03.csv"),
    "retry-s01-t04-evidence-04.yaml": parse_yaml(f"{base}/retry-s01-t04-evidence-04.yaml"),
    "retry-s01-t04-evidence-05.log": parse_log(f"{base}/retry-s01-t04-evidence-05.log"),
}

for name, recs in files.items():
    print(name, "parsed records:", len(recs))

min_count = min(len(r) for r in files.values())
shared_ids = [f"retry-s01-t04-{i:06d}" for i in range(1, min_count+1)]
print("shared range: 1 to", min_count)

names = list(files.keys())
mismatches = []
for cid in shared_ids:
    values = [files[n].get(cid) for n in names]
    if len(set(values)) > 1:
        mismatches.append((cid, dict(zip(names, values))))

print("mismatches over shared range:", len(mismatches))
for m in mismatches[:10]:
    print(m)
PY

