python3 - "$D" <<'EOF'
import sys, re, json, csv, hashlib

D = sys.argv[1]

def sha(path):
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()

# md
md_path = f"{D}/retry-s01-t10-evidence-01.md"
md_records = []
with open(md_path) as f:
    for line in f:
        m = re.match(r"- \*\*(retry-s01-t10-\d+)\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \| Evidence: (.*)$", line.strip())
        if m:
            md_records.append(m.groups())

# jsonl
jsonl_path = f"{D}/retry-s01-t10-evidence-02.jsonl"
jsonl_records = []
with open(jsonl_path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        jsonl_records.append((obj["case"], obj["system"], obj["status"], obj["note"]))

# csv
csv_path = f"{D}/retry-s01-t10-evidence-03.csv"
csv_records = []
with open(csv_path, newline="") as f:
    reader = csv.DictReader(f)
    for row in reader:
        csv_records.append((row["case"], row["system"], row["status"], row["note"]))

# yaml (manual parse, simple structure)
yaml_path = f"{D}/retry-s01-t10-evidence-04.yaml"
yaml_records = []
cur = {}
with open(yaml_path) as f:
    for line in f:
        line = line.rstrip("\n")
        m = re.match(r"- case: (.+)$", line)
        if m:
            if cur:
                yaml_records.append((cur.get("case"), cur.get("system"), cur.get("status"), cur.get("note")))
            cur = {"case": m.group(1)}
            continue
        m = re.match(r"  system: (.+)$", line)
        if m:
            cur["system"] = m.group(1)
            continue
        m = re.match(r"  status: (.+)$", line)
        if m:
            cur["status"] = m.group(1)
            continue
        m = re.match(r'  note: "(.*)"$', line)
        if m:
            cur["note"] = m.group(1)
            continue
    if cur:
        yaml_records.append((cur.get("case"), cur.get("system"), cur.get("status"), cur.get("note")))

# log
log_path = f"{D}/retry-s01-t10-evidence-05.log"
log_records = []
with open(log_path) as f:
    for line in f:
        line = line.strip()
        m = re.match(r'case=(\S+) system=(\S+) status=(\S+) note="(.*)"$', line)
        if m:
            log_records.append(m.groups())

sets = {
    "md (01)": md_records,
    "jsonl (02)": jsonl_records,
    "csv (03)": csv_records,
    "yaml (04)": yaml_records,
    "log (05)": log_records,
}

for name, recs in sets.items():
    print(f"{name}: {len(recs)} records, first={recs[0][0] if recs else None}, last={recs[-1][0] if recs else None}")

print()
# check field-level cross-consistency for the case IDs common to all
case_ids_sets = {name: set(r[0] for r in recs) for name, recs in sets.items()}
all_common = set.intersection(*case_ids_sets.values())
all_union = set.union(*case_ids_sets.values())
print(f"Common to all 5 files: {len(all_common)} cases")
print(f"Union across all 5 files: {len(all_union)} cases")

for name, s in case_ids_sets.items():
    only = s - all_common
    print(f"{name}: {len(s)} total cases; {len(only)} not in the common set: {sorted(only)[:5]}{'...' if len(only)>5 else ''}")

# check that within the common set, all fields match across files
by_name = {}
for name, recs in sets.items():
    by_name[name] = {r[0]: r for r in recs}

mismatches = []
for cid in sorted(all_common):
    rows = {name: by_name[name][cid] for name in sets}
    ref = rows["md (01)"]
    for name, row in rows.items():
        if row != ref:
            mismatches.append((cid, name, row, ref))

print(f"\nField mismatches among common cases: {len(mismatches)}")
for m in mismatches[:10]:
    print(m)

print()
print("SHA256 checksums:")
for fn in ["retry-s01-t10-evidence-01.md","retry-s01-t10-evidence-02.jsonl","retry-s01-t10-evidence-03.csv","retry-s01-t10-evidence-04.yaml","retry-s01-t10-evidence-05.log"]:
    print(fn, sha(f"{D}/{fn}"))
EOF

