import sys, re, json, csv

D = sys.argv[1]

def get_ids(path, pattern_type):
    ids = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if pattern_type == "md":
                m = re.match(r"- \*\*(retry-s01-t10-\d+)\*\*", line)
                if m: ids.append(m.group(1))
            elif pattern_type == "jsonl":
                if line:
                    ids.append(json.loads(line)["case"])
            elif pattern_type == "log":
                m = re.match(r"case=(\S+)", line)
                if m: ids.append(m.group(1))
    return ids

md_ids = get_ids(f"{D}/retry-s01-t10-evidence-01.md", "md")
jsonl_ids = get_ids(f"{D}/retry-s01-t10-evidence-02.jsonl", "jsonl")
log_ids = get_ids(f"{D}/retry-s01-t10-evidence-05.log", "log")

with open(f"{D}/retry-s01-t10-evidence-03.csv", newline="") as f:
    csv_ids = [row["case"] for row in csv.DictReader(f)]

yaml_ids = []
with open(f"{D}/retry-s01-t10-evidence-04.yaml") as f:
    for line in f:
        m = re.match(r"- case: (.+)$", line.strip())
        if m: yaml_ids.append(m.group(1))

sets_ordered = [("jsonl(02)", jsonl_ids), ("md(01)", md_ids), ("yaml(04)", yaml_ids), ("log(05)", log_ids), ("csv(03)", csv_ids)]
for name, ids in sets_ordered:
    print(name, len(ids), ids[0], "..", ids[-1], "contiguous:", ids == [f"retry-s01-t10-{i:06d}" for i in range(1, len(ids)+1)])

# check strict nesting/prefix relationship
for i in range(len(sets_ordered)-1):
    n1, s1 = sets_ordered[i]
    n2, s2 = sets_ordered[i+1]
    is_prefix = s2[:len(s1)] == s1
    print(f"{n1} is exact prefix of {n2}: {is_prefix}")
