D="/private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-xa2ygylo/retry-s01-worker-crash/maintenance/inputs/retry-s01/duplicate-delivery-observations"
python3 - "$D" <<'EOF'
import sys, re, json, csv, hashlib

D = sys.argv[1]

def sha(path):
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()

def get_ids(path, pattern_type):
    ids = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if pattern_type == "md":
                m = re.match(r"- \*\*(retry-s01-t11-\d+)\*\*", line)
                if m: ids.append(m.group(1))
            elif pattern_type == "jsonl":
                if line:
                    ids.append(json.loads(line)["case"])
            elif pattern_type == "log":
                m = re.match(r"case=(\S+)", line)
                if m: ids.append(m.group(1))
    return ids

md_path = f"{D}/retry-s01-t11-evidence-01.md"
jsonl_path = f"{D}/retry-s01-t11-evidence-02.jsonl"
csv_path = f"{D}/retry-s01-t11-evidence-03.csv"
yaml_path = f"{D}/retry-s01-t11-evidence-04.yaml"
log_path = f"{D}/retry-s01-t11-evidence-05.log"

def parse_full(path, kind):
    recs = []
    if kind == "md":
        with open(path) as f:
            for line in f:
                m = re.match(r"- \*\*(retry-s01-t11-\d+)\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \| Evidence: (.*)$", line.strip())
                if m: recs.append(m.groups())
    elif kind == "jsonl":
        with open(path) as f:
            for line in f:
                line = line.strip()
                if line:
                    o = json.loads(line)
                    recs.append((o["case"], o["system"], o["status"], o["note"]))
    elif kind == "csv":
        with open(path, newline="") as f:
            for row in csv.DictReader(f):
                recs.append((row["case"], row["system"], row["status"], row["note"]))
    elif kind == "yaml":
        cur = {}
        with open(path) as f:
            for line in f:
                line = line.rstrip("\n")
                m = re.match(r"- case: (.+)$", line)
                if m:
                    if cur: recs.append((cur.get("case"), cur.get("system"), cur.get("status"), cur.get("note")))
                    cur = {"case": m.group(1)}; continue
                m = re.match(r"  system: (.+)$", line)
                if m: cur["system"]=m.group(1); continue
                m = re.match(r"  status: (.+)$", line)
                if m: cur["status"]=m.group(1); continue
                m = re.match(r'  note: "(.*)"$', line)
                if m: cur["note"]=m.group(1); continue
            if cur: recs.append((cur.get("case"), cur.get("system"), cur.get("status"), cur.get("note")))
    elif kind == "log":
        with open(path) as f:
            for line in f:
                m = re.match(r'case=(\S+) system=(\S+) status=(\S+) note="(.*)"$', line.strip())
                if m: recs.append(m.groups())
    return recs

files = [
    ("md(01)", md_path, "md"),
    ("jsonl(02)", jsonl_path, "jsonl"),
    ("csv(03)", csv_path, "csv"),
    ("yaml(04)", yaml_path, "yaml"),
    ("log(05)", log_path, "log"),
]

recs_by_name = {}
for name, path, kind in files:
    recs = parse_full(path, kind)
    recs_by_name[name] = recs
    ids = [r[0] for r in recs]
    contiguous = ids == [f"retry-s01-t11-{i:06d}" for i in range(1, len(ids)+1)]
    print(f"{name}: {len(recs)} records, range {ids[0]}..{ids[-1]}, contiguous={contiguous}")

# sort by length to check nesting
ordered = sorted(files, key=lambda x: len(recs_by_name[x[0]]))
names_sorted = [o[0] for o in ordered]
print("\nOrder by size:", names_sorted)
for i in range(len(names_sorted)-1):
    n1, n2 = names_sorted[i], names_sorted[i+1]
    ids1 = [r[0] for r in recs_by_name[n1]]
    ids2 = [r[0] for r in recs_by_name[n2]]
    is_prefix = ids2[:len(ids1)] == ids1
    print(f"{n1} is exact prefix of {n2}: {is_prefix}")

# field consistency check among common cases
common = set(recs_by_name[names_sorted[0]] and [r[0] for r in recs_by_name[names_sorted[0]]])
common = set([r[0] for r in recs_by_name[names_sorted[0]]])
by_id = {name: {r[0]: r for r in recs} for name, recs in recs_by_name.items()}
mismatches = []
for cid in common:
    ref = by_id[names_sorted[0]][cid]
    for name in names_sorted:
        row = by_id[name].get(cid)
        if row is not None and row != ref:
            mismatches.append((cid, name, row, ref))
print(f"\nField mismatches among common (smallest-file) cases: {len(mismatches)}")

print("\nSHA256:")
for name, path, kind in files:
    print(path.split("/")[-1], sha(path))
EOF

